local NewViewBaseLayer = require("hall.NewViewBaseLayer")
local ReminderView = class("ReminderView", NewViewBaseLayer)

local EVENTNAME = {
	GET_MSG_FOR_PLAYER_GROUP = "/getMsgForplayerGroup",
	UPDATE_APPLY_FOR_STATUS = "/updateApplyForStatus",
}

function ReminderView:ctor(family_id)
    self.family_id = family_id
    local csbPath = "hall/res/FriendScircle/ReminderView.csb"
    ReminderView.super.ctor(self, csbPath)

    self:enableMask(true)
    self:initEvent()
    self.dataList = {}
	self.allData = {}
    self.curPage = 1
	self.page_num = 10
	self.tatolPage = 1
    self:createTableView()
    self:InitGame()
end

function ReminderView:initEvent()
    self.item:hide()
    self.btn_share:hide()
	
    ReqMgr:addHandle("ReminderView", EVENTNAME)
    self.btn_r:onClick(handler(self, self.btn_r_page))
    self.btn_l:onClick(handler(self, self.btn_l_page))
end

function ReminderView:onExit()
    ReqMgr:delHandle("ReminderView", EVENTNAME)
end

function ReminderView:createTableView()
    local size = self.ListView_1:getSize()
    local getAnchorPoint = self.ListView_1:getAnchorPoint()
    local getPosition = self.ListView_1:getPosition()
    self.userList = cc.TableView:create(size)
    self.userList:setDirection(cc.SCROLLVIEW_DIRECTION_VERTICAL)
    self.userList:setVerticalFillOrder(cc.TABLEVIEW_FILL_TOPDOWN)
    self.userList:setAnchorPoint(getAnchorPoint)
    self.userList:setPosition(getPosition)
    self.userList:setDelegate()
   
    self.userList:addTo(self.root,99)
    self.userList:registerScriptHandler(handler(self, self.tableCellAtIndex), cc.TABLECELL_SIZE_AT_INDEX)
    self.userList:registerScriptHandler(handler(self, self.tableCellTouched), cc.TABLECELL_TOUCHED)
    self.userList:registerScriptHandler(handler(self, self.cellSizeForTable), cc.TABLECELL_SIZE_FOR_INDEX)
    self.userList:registerScriptHandler(handler(self, self.numberOfCellsInTableView), cc.NUMBER_OF_CELLS_IN_TABLEVIEW)
    self.userList:reloadData()
end

--test
function ReminderView:tableCellAtIndex(view, idx)
    local cell = view:dequeueCell()
    local item = nil
    if nil == cell then
        cell = cc.TableViewCell:new()
        local userBar = self:createUser(self.dataList[idx+1], idx + 1)
        cell:addChild(userBar)
    else
        local node = cell:getChildByName("ly"):getChildByName("item")
        self:initCellInfo(node,self.dataList[idx+1], idx + 1)
    end
    return cell
end

function ReminderView:initCellInfo(item, data, index)
    dump(data)
    local nickName = data.nickName or ""
    local playerId = data.playerId or ""
    local str = string.format("%s (ID: %s ) ", nickName, playerId)
    if data.status == 0 then
        str = str .. "申请加入联盟,是否同意?"
    elseif data.status == 5 then
        str = str .. "邀请你加入联盟,是否同意?"
    end
    item.nameAndId:setString(str)
    item.btnAgree.msgId = data.id
    item.btnAgree.status = data.status
    item.btnAgree.playerId = data.playerId
    item.btnAgree:onClick(handler(self, self.onClickBtnAgree))

    item.btn_refuse.msgId = data.id
    item.btn_refuse.status = data.status
    item.btn_refuse.playerId = data.playerId
    item.btn_refuse:onClick(handler(self, self.onClickBtnRefuse))
end

function ReminderView:onClickBtnAgree( event )
    local data = {}
    local target = event.target
    local msgId = target.msgId
    local playerId = target.playerId
    --POST /updateApplyForStatus群主处理玩家的申请信息 0:待审核 1:通过 2:忽略 3:拒绝 4:已读 5:邀请 6:同意 7:拒绝
    local data = {
        XYUid = USER_INFO["uid"],
        msgId = msgId,
        status = 6,
    }
    if target.status == 5 then
        data.status = 6
    elseif target.status == 0 then
        data.status = 1
    end
    dump(data)
    ReqMgr:request(EVENTNAME.UPDATE_APPLY_FOR_STATUS, data, handler(self , self.UPDATE_APPLY_FOR_STATUS))
end

function ReminderView:onClickBtnRefuse( event )
    local data = {}
    local target = event.target
    local msgId = target.msgId
    local playerId = target.playerId
    --POST /updateApplyForStatus群主处理玩家的申请信息 0:待审核 1:通过 2:忽略 3:拒绝 4:已读 5:邀请 6:同意 7:拒绝
    local data = {
