function ReminderView:UPDATE_APPLY_FOR_STATUS( event )
    local netData = event.netData
	local param = event.param
	local returnCode = netData.returnCode
	local data = netData.data
    local error = netData.error
    if not (returnCode == 0) then
        viewMgr:showTip({text = error})
        return
    end
    viewMgr:showTip({text = data})
    self:InitGame()
    dump(data)

    if g_hallMainLayer and g_hallMainLayer.btnMsgRed then
        if #data > 0 then
            g_hallMainLayer.btnMsgRed:setVisible(true)
        else
            g_hallMainLayer.btnMsgRed:setVisible(false)
        end
    end
    USER_INFO["msgCount"] = #data
end

