end

function ReminderView:InitGame(page, playerId)
	page = page or 1
    -- local data = {groupId = self.family_id, playerId = USER_INFO.uid, pageSize = self.page_num, currentPage = page}
    local data = {
        playerId = USER_INFO["uid"] ,
        -- groupId = self.family_id,
        -- status = 0
    }
    -- dump(data)
    ReqMgr:request(EVENTNAME.GET_MSG_FOR_PLAYER_GROUP, data, handler(self , self.GET_MSG_FOR_PLAYER_GROUP), {page = page})
end

function ReminderView:GET_MSG_FOR_PLAYER_GROUP(event)
    local netData = event.netData
	local param = event.param
	local returnCode = netData.returnCode
	local data = netData.data
    local error = netData.error
    dump(returnCode)
    dump(error)
    dump(data)
    if not (returnCode == 0) then
        viewMgr:showTip({text = error})
        return
    end

    self.allData = data or {}
    local number = #self.allData
    self.tatolPage = math.ceil(number / self.page_num)
    self.dataList = data or {}
	if self.tatolPage == 0 then
        self.tatolPage = 1
    end
    if g_hallMainLayer and g_hallMainLayer.btnMsgRed then
        if #self.dataList > 0 then
            g_hallMainLayer.btnMsgRed:setVisible(true)
        else
            g_hallMainLayer.btnMsgRed:setVisible(false)
        end
    end
    USER_INFO["msgCount"] = #self.dataList


    self:handleData(1)
end

function ReminderView:reloadData(data)
    if not data then return end
    self.dataList = data
    self.userList:reloadData()
end

function ReminderView:onClickBtnReturn(...)
    self:removeSelf()
end

function ReminderView:handleData(curPage)
    local startIdx = (self.curPage-1) * self.page_num
    local data = table.slice(self.allData, startIdx, self.page_num, true)
    self:reloadData(data)
    self.txt_page:setString(self.curPage.."/"..self.tatolPage)
end

function ReminderView:btn_r_page()
	local page = self.curPage + 1
	if page <= 0 or page > self.tatolPage or self.curPage == page then
		return
    end
    self.curPage = page
    self:handleData(page)
end

function ReminderView:btn_l_page()
	local page = self.curPage - 1
	if page <= 0 or page > self.tatolPage or self.curPage == page then
		return
	end
    self.curPage = page
    self:handleData(page)
end

return ReminderView